package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.springframework.jdbc.datasource.DelegatingDataSource;

/** Hands out connections pointed at the as-of schema while a request is shown as of a date, so
 *  every read in the app sees the sheet as it stood then. The pool resets the schema on return. */
public class AsOfDataSource extends DelegatingDataSource {

    public AsOfDataSource(DataSource target) {
        super(target);
    }

    @Override
    public Connection getConnection() throws SQLException {
        return point(super.getConnection());
    }

    @Override
    public Connection getConnection(String username, String password) throws SQLException {
        return point(super.getConnection(username, password));
    }

    private static Connection point(Connection connection) throws SQLException {
        String schema = AsOfView.schema();
        if (schema != null) {
            connection.setSchema(schema);
        }
        return connection;
    }
}
package net.officefloor.hq.app.asof;

import javax.sql.DataSource;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.stereotype.Component;

/** Wraps the app's DataSource in {@link AsOfDataSource}. */
@Component
public class AsOfDataSourceWrapper implements BeanPostProcessor {

    @Override
    public Object postProcessAfterInitialization(Object bean, String beanName) {
        if (bean instanceof DataSource dataSource && !(bean instanceof AsOfDataSource)) {
            return new AsOfDataSource(dataSource);
        }
        return bean;
    }
}
package net.officefloor.hq.app.asof;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.UriUtils;

/**
 * A request about a sheet carrying {@code shown-asof=<yyyy-MM-dd>} comes from a screen showing the sheet as
 * of that date. A read (any GET, and loading the sheet) is answered from the sheet as it stood then
 * ({@link AsOfStore}), with the date as its today; every change is refused (403) before anything is
 * read or written, so nothing reaches the store or the audit file.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 100)
public class AsOfFilter extends OncePerRequestFilter {

    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final AsOfStore store;

    public AsOfFilter(AsOfStore store) {
        this.store = store;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String asOf = request.getParameter("shown-asof");
        Matcher sheet = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        if (!sheet.matches()) {
            chain.doFilter(request, response);
            return;
        }
        boolean read = "GET".equals(request.getMethod())
                || ("POST".equals(request.getMethod()) && "/open".equals(sheet.group(2)));
        if (asOf == null || asOf.isBlank()) {
            preview(request, response, chain, sheet, read);
            return;
        }
        if (!read) {
            refuse(response, HttpStatus.FORBIDDEN, "The sheet is shown as of a date: nothing can be changed");
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(asOf.trim());
        } catch (DateTimeParseException e) {
            refuse(response, HttpStatus.BAD_REQUEST, "Not a date: " + asOf);
            return;
        }
        String schema = store.view(UriUtils.decode(sheet.group(1), StandardCharsets.UTF_8).trim(), date);
        AsOfView.enter(schema);
        try {
            chain.doFilter(request, response);
        } finally {
            AsOfView.leave();
            store.drop(schema);
        }
    }

    /**
     * A read carrying {@code shown-preview=<yyyy-MM-dd>} comes from a screen previewing that date: it is
     * answered from what the sheet holds now with the date as its today. A change is never previewed: it
     * goes by the sheet's real today. The view is thrown away after, so nothing a read does stays.
     */
    private void preview(HttpServletRequest request, HttpServletResponse response, FilterChain chain, Matcher sheet,
            boolean read) throws ServletException, IOException {
        String preview = request.getParameter("shown-preview");
        if (!read || preview == null || preview.isBlank()) {
            chain.doFilter(request, response);
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(preview.trim());
        } catch (DateTimeParseException e) {
            refuse(response, HttpStatus.BAD_REQUEST, "Not a date: " + preview);
            return;
        }
        String schema = store.preview(UriUtils.decode(sheet.group(1), StandardCharsets.UTF_8).trim(), date);
        if (schema == null) {
            chain.doFilter(request, response);
            return;
        }
        AsOfView.enter(schema);
        try {
            chain.doFilter(request, response);
        } finally {
            AsOfView.leave();
            store.drop(schema);
        }
    }

    private static void refuse(HttpServletResponse response, HttpStatus status, String message) throws IOException {
        response.setStatus(status.value());
        response.setContentType("text/plain;charset=UTF-8");
        response.getWriter().write(message);
    }
}
package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import javax.sql.DataSource;
import net.officefloor.hq.app.rate.RateRepository;
import org.springframework.stereotype.Component;

/**
 * What a sheet held as of a date. Each time the sheet's today changes, its rows are copied into a
 * schema of their own (SNAP_<id>, listed in sheet_snapshot). The sheet as of a date is what it held
 * at the last moment its today was on or before that date: the store as it is now while its today
 * still is, else the copy taken when its today last moved past that date, else nothing. A view
 * copies that into a schema the request reads (ASOF_<n>), with the date as the sheet's today, and
 * drops it after.
 *
 * Works on connections of its own, so a copy is never part of a request's transaction, and one copy
 * or drop at a time: H2 lets one session at a time change its schemas.
 */
@Component
public class AsOfStore {

    private static final String LIVE = "PUBLIC";

    /** Tables that are not the sheet's data. */
    private static final Set<String> SKIP = Set.of("flyway_schema_history", "SHEET_SNAPSHOT");

    private final DataSource dataSource;

    private final AtomicLong views = new AtomicLong();

    /** The live tables and their columns: the schema is migrated before the app serves, so they are read once. */
    private List<String> liveTables;

    private final Map<String, Set<String>> liveColumns = new HashMap<>();

    public AsOfStore(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    /** Keep what the sheet holds now, before its today moves from {@code was} to {@code now}. */
    public synchronized void snapshot(String sheetId, LocalDate was, LocalDate now) {
        try (Connection c = dataSource.getConnection()) {
            c.setAutoCommit(true);
            long id;
            try (Statement s = c.createStatement();
                    ResultSet rs = s.executeQuery("SELECT NEXT VALUE FOR sheet_snapshot_seq")) {
                rs.next();
                id = rs.getLong(1);
            }
            copy(c, LIVE, "SNAP_" + id, sheetId);
            try (PreparedStatement ps = c.prepareStatement(
                    "INSERT INTO sheet_snapshot (id, sheet_id, today_was, today_now) VALUES (?, ?, ?, ?)")) {
                ps.setLong(1, id);
                ps.setString(2, sheetId);
                ps.setObject(3, was);
                ps.setObject(4, now);
                ps.executeUpdate();
            }
        } catch (SQLException e) {
            throw new IllegalStateException("Could not keep the sheet as of its today", e);
        }
    }

    /** A new schema holding the sheet as of the date, with the date as its today. */
    public String view(String sheetId, LocalDate asOf) {
        return view(sheetId, asOf, false);
    }

    /** A new schema holding what the sheet holds now, with the date as its today (a preview of that
     *  date over its current records); null when the sheet was never loaded. */
    public String preview(String sheetId, LocalDate date) {
        return view(sheetId, date, true);
    }

    private synchronized String view(String sheetId, LocalDate asOf, boolean preview) {
        String schema = (preview ? "PREVIEW_" : "ASOF_") + views.incrementAndGet();
        try (Connection c = dataSource.getConnection()) {
            c.setAutoCommit(true);
            String[] sheet = liveSheet(c, sheetId);
            if (preview && sheet == null) return null;
            String source;
            // The day the source was taken on: its SNAPSHOT lines for that day were written as it was left.
            LocalDate leftFrom = asOf;
            if (preview || (sheet != null && !LocalDate.parse(sheet[1]).isAfter(asOf))) {
                source = LIVE;
            } else {
                source = null;
                try (PreparedStatement ps = c.prepareStatement("SELECT id, today_was FROM sheet_snapshot "
                        + "WHERE sheet_id = ? AND today_was <= ? AND today_now > ? ORDER BY id DESC LIMIT 1")) {
                    ps.setString(1, sheetId);
                    ps.setObject(2, asOf);
                    ps.setObject(3, asOf);
                    try (ResultSet rs = ps.executeQuery()) {
                        if (rs.next()) {
                            source = "SNAP_" + rs.getLong(1);
                            leftFrom = rs.getObject(2, LocalDate.class);
                        }
                    }
                }
            }
            copy(c, source, schema, sheetId);
            if (source == null) {
                // Nothing on it yet: the sheet itself, as it was made.
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + ".SHEET "
                        + "(ID, CREATED_BY, CREATED_AT, TODAY, LAST_CLAIM_NUMBER, ARCHIVED) "
                        + "VALUES (?, ?, CURRENT_TIMESTAMP, ?, 0, FALSE)")) {
                    ps.setString(1, sheetId);
                    ps.setString(2, sheet == null ? "" : sheet[0]);
                    ps.setObject(3, asOf);
                    ps.executeUpdate();
                }
            }
            // The parent link is not dated: the view names the parent the sheet names now.
            try (PreparedStatement ps = c.prepareStatement(
                    "DELETE FROM " + q(schema) + ".SHEET_SETTING WHERE SHEET_ID = ? AND SETTING = 'parent'")) {
                ps.setString(1, sheetId);
                ps.executeUpdate();
            }
            try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + ".SHEET_SETTING SELECT * FROM "
                    + "PUBLIC.SHEET_SETTING WHERE SHEET_ID = ? AND SETTING = 'parent'")) {
                ps.setString(1, sheetId);
                ps.executeUpdate();
            }
            // A grade without a rate of its own goes by its ancestors' (as they stood on the date, see RateRepository):
            // their rates, parent links and clone sources come along, as far as rates are looked.
            List<String> chain;
            try {
                chain = RateRepository.chain(sheetId, (at) -> live(() -> liveParent(c, at)),
                        (at) -> live(() -> liveSource(c, at)));
            } catch (UncheckedSql e) {
                throw e.getCause();
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "DELETE FROM " + q(schema) + ".SHEET_SOURCE WHERE SHEET_ID = ?")) {
                ps.setString(1, sheetId);
                ps.executeUpdate();
            }
            List<String> linked = new ArrayList<>(List.of(sheetId));
            linked.addAll(chain);
            for (String at : linked) {
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + ".SHEET_SOURCE SELECT * FROM "
                        + "PUBLIC.SHEET_SOURCE WHERE SHEET_ID = ?")) {
                    ps.setString(1, at);
                    ps.executeUpdate();
                }
            }
            for (String at : chain) {
                for (String table : List.of("RATE", "RATE_VERSION", "RATE_HISTORY")) {
                    try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + "." + q(table)
                            + " SELECT * FROM PUBLIC." + q(table) + " WHERE SHEET_ID = ?")) {
                        ps.setString(1, at);
                        ps.executeUpdate();
                    }
                }
                try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + ".SHEET_SETTING SELECT * FROM "
                        + "PUBLIC.SHEET_SETTING WHERE SHEET_ID = ? AND SETTING = 'parent'")) {
                    ps.setString(1, at);
                    ps.executeUpdate();
                }
            }
            // A SNAPSHOT is written when its day is left: as of that day (or before) it was not there yet.
            // A preview keeps every record the sheet holds now.
            if (!preview) {
                try (PreparedStatement ps = c.prepareStatement(
                        "DELETE FROM " + q(schema) + ".PERSON_SNAPSHOT WHERE SHEET_ID = ? AND DAY_LEFT >= ?")) {
                    ps.setString(1, sheetId);
                    ps.setObject(2, leftFrom);
                    ps.executeUpdate();
                }
            }
            try (PreparedStatement ps = c.prepareStatement(
                    "UPDATE " + q(schema) + ".SHEET SET TODAY = ? WHERE ID = ?")) {
                ps.setObject(1, asOf);
                ps.setString(2, sheetId);
                ps.executeUpdate();
            }
            return schema;
        } catch (SQLException e) {
            drop(schema);
            throw new IllegalStateException("Could not show the sheet as of " + asOf, e);
        }
    }

    /** Works something out from the sheet as of the date, as a request shown as of it would: on a thread of
     *  its own, so it reads the view on connections of its own, outside the caller's transaction. */
    public <T> T read(String sheetId, LocalDate asOf, java.util.function.Supplier<T> work) {
        String schema = view(sheetId, asOf);
        try {
            java.util.concurrent.FutureTask<T> task = new java.util.concurrent.FutureTask<>(() -> {
                AsOfView.enter(schema);
                try {
                    return work.get();
                } finally {
                    AsOfView.leave();
                }
            });
            Thread thread = new Thread(task, "as-of-" + schema);
            thread.start();
            try {
                return task.get();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("Interrupted reading the sheet as of " + asOf, e);
            } catch (java.util.concurrent.ExecutionException e) {
                if (e.getCause() instanceof RuntimeException r) throw r;
                throw new IllegalStateException("Could not read the sheet as of " + asOf, e.getCause());
            }
        } finally {
            drop(schema);
        }
    }

    /** Drop a view's schema once its request is done. */
    public synchronized void drop(String schema) {
        try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
            c.setAutoCommit(true);
            s.execute("DROP SCHEMA IF EXISTS " + q(schema) + " CASCADE");
        } catch (SQLException e) {
            // left behind: it is never read again
        }
    }

    /** The live sheet's creator and today, or null when it was never loaded. */
    private static String[] liveSheet(Connection c, String sheetId) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement("SELECT created_by, today FROM PUBLIC.sheet WHERE id = ?")) {
            ps.setString(1, sheetId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? new String[] { rs.getString(1), rs.getObject(2, LocalDate.class).toString() } : null;
            }
        }
    }

    /** The sheet's parent as the live store names it now; null when it has none. */
    private static String liveParent(Connection c, String sheetId) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement(
                "SELECT val FROM PUBLIC.SHEET_SETTING WHERE SHEET_ID = ? AND SETTING = 'parent'")) {
            ps.setString(1, sheetId);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    String v = rs.getString(1);
                    if (v != null && !v.isEmpty()) return v;
                }
                return null;
            }
        }
    }

    /** The sheet the sheet was cloned from, as the live store names it; null when it was not cloned. */
    private static String liveSource(Connection c, String sheetId) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement("SELECT source_id FROM PUBLIC.SHEET_SOURCE WHERE SHEET_ID = ?")) {
            ps.setString(1, sheetId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getString(1) : null;
            }
        }
    }

    private interface SqlLookup {
        String get() throws SQLException;
    }

    private static final class UncheckedSql extends RuntimeException {
        UncheckedSql(SQLException cause) {
            super(cause);
        }

        @Override
        public synchronized SQLException getCause() {
            return (SQLException) super.getCause();
        }
    }

    private static String live(SqlLookup lookup) {
        try {
            return lookup.get();
        } catch (SQLException e) {
            throw new UncheckedSql(e);
        }
    }

    /** Copy the sheet's rows of every table from {@code source} (null: none) into a new schema. */
    private void copy(Connection c, String source, String target, String sheetId) throws SQLException {
        if (liveTables == null) liveTables = tables(c, LIVE);
        List<String> tables = liveTables;
        // A snapshot is a copy of every live table, all taken since the app started.
        Set<String> inSource = source == null ? Set.of() : new HashSet<>(source.equals(LIVE) || source.startsWith("SNAP_") ? tables : tables(c, source));
        String sheet = "'" + sheetId.replace("'", "''") + "'";
        try (Statement s = c.createStatement()) {
            s.execute("CREATE SCHEMA " + q(target));
            for (String table : tables) {
                boolean has = inSource.contains(table);
                String from = q(has ? source : LIVE);
                String where = has ? filter(c, table, from, sheet) : "FALSE";
                s.execute("CREATE TABLE " + q(target) + "." + q(table) + " AS SELECT * FROM " + from + "."
                        + q(table) + " WHERE " + where);
            }
        }
    }

    /** The condition picking the sheet's rows of a table. */
    private String filter(Connection c, String table, String from, String sheet) throws SQLException {
        if (table.equals("SHEET")) return "ID = " + sheet;
        Set<String> columns = liveColumns.get(table);
        if (columns == null) {
            columns = columns(c, table);
            liveColumns.put(table, columns);
        }
        if (columns.contains("SHEET_ID")) return "SHEET_ID = " + sheet;
        for (String owner : List.of("PERIOD", "PERSON", "CLAIM")) {
            if (columns.contains(owner + "_ID")) {
                return owner + "_ID IN (SELECT ID FROM " + from + "." + owner + " WHERE SHEET_ID = " + sheet + ")";
            }
        }
        return "TRUE";
    }

    private static List<String> tables(Connection c, String schema) throws SQLException {
        List<String> tables = new ArrayList<>();
        try (PreparedStatement ps = c.prepareStatement("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES "
                + "WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME")) {
            ps.setString(1, schema);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    if (!SKIP.contains(rs.getString(1))) tables.add(rs.getString(1));
                }
            }
        }
        return tables;
    }

    private static Set<String> columns(Connection c, String table) throws SQLException {
        Set<String> columns = new HashSet<>();
        try (PreparedStatement ps = c.prepareStatement("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
                + "WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?")) {
            ps.setString(1, LIVE);
            ps.setString(2, table);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) columns.add(rs.getString(1));
            }
        }
        return columns;
    }

    private static String q(String identifier) {
        return "\"" + identifier.replace("\"", "\"\"") + "\"";
    }
}
